from z3 import *

# 11 vertices
n = 11

# Variables for edges
edges = {}
for i in range(n):
    for j in range(i+1, n):
        edges[(i, j)] = Bool(f"e_{i}_{j}")

s = Solver()

# Partial assignment
known_edges = [(5,6), (3,8), (0,9), (3,7), (3,9), (4,9)]
for i in range(n):
    for j in range(i+1, n):
        if (i, j) in known_edges or (j, i) in known_edges:
            u, v = min(i, j), max(i, j)
            s.add(edges[(u, v)] == True)

# Degree constraints
for i in range(n):
    deg_i = []
    for j in range(n):
        if i != j:
            u, v = min(i, j), max(i, j)
            deg_i.append(If(edges[(u, v)], 1, 0))

    s.add(Sum(deg_i) >= 4)
    s.add(Sum(deg_i) <= 6)

if s.check() == sat:
    m = s.model()
    res = []
    for i in range(n):
        for j in range(i+1, n):
            if is_true(m[edges[(i, j)]]):
                res.append([i, j])
    print("SAT")
    print(res)
else:
    print("UNSAT")
